head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 화면에서 선택 표시(하이라이트)된 Body Cell 개수를 센다
scwin.countHighlightedCell = function (objGrid) {
    var arrCell = objGrid.render.querySelectorAll("td");
    var nCount = 0;

    for (var i = 0; i < arrCell.length; i++) {
        if (/focus|select/i.test(arrCell[i].className || "")) {
            nCount++;
        }
    }
    return nCount;
};

scwin.btn_check_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");
    var arrFocused = objGrid.getAllFocusedIndex();

    scwin.setReturnValue("getAllFocusedIndex : " + JSON.stringify(arrFocused));
    scwin.setReturnValue("getAllFocusedIndex 개수 : " + (arrFocused ? arrFocused.length : 0));
    scwin.setReturnValue("화면에서 선택 표시된 Cell 개수 : " + scwin.countHighlightedCell(objGrid));
};
